{
  "schema_version": 1,
  "name": "graded_belief_allocation_reference",
  "summary": "Graded belief allocation (10-point bet) across referents on informative and prior trials over 3-5 objects and 2-4 features, testing recursive pragmatic reasoning, graded lexical truth, competitor confusion, and singleton heuristics.",
  "charter": {
    "question": "When listeners distribute graded credence across candidate referents on informative and uninformative trials, do their full belief distributions follow recursive pragmatic inference with shared perceptual priors, depth-3 graded lexical precision, competitor-confusion avoidance, or a non-Bayesian singleton oddity heuristic?"
  },
  "instructions": {
    "welcome": "Welcome! In this study, you will look at sets of objects (such as houses, robots, or snowmen) and figure out which object a speaker is talking about.",
    "task": "On each turn, both you and the speaker see the same row of objects. The speaker secretly has one target object in mind and says a single word that is true of their target object (for example, a part that the object has). Your job is to distribute 10 points across the objects to show how likely each object is to be the speaker's target. Put more points on objects you think are more likely, and 0 points on objects that cannot be the target. Your points on each turn must add up to 10. On some turns, the speaker's word is missing, so you will distribute your 10 points based only on which object you think the speaker is most likely to talk about.",
    "comprehension_checks": [
      {
        "question": "How many total points must you distribute across the objects on each turn?",
        "options": [
          "Exactly 10 points in total across the objects.",
          "10 points for every single object on the screen.",
          "As many or as few points as you want, with no fixed total."
        ],
        "correct": 0
      },
      {
        "question": "When the speaker says a word (like a part of an object), which objects can be the speaker's target?",
        "options": [
          "An object that actually has that part, chosen by a helpful speaker who sees all the objects.",
          "Only objects that do not have that part.",
          "Always the object on the far left of the screen."
        ],
        "correct": 0
      }
    ]
  },
  "materials": {
    "kind": "svg",
    "domains": [
