            "svg": "<rect x=\"61\" y=\"18\" width=\"11\" height=\"22\" fill=\"#a93226\" stroke=\"#4a2311\" stroke-width=\"1.6\"/><rect x=\"59\" y=\"15\" width=\"15\" height=\"4\" rx=\"1\" fill=\"#922b21\" stroke=\"#4a2311\" stroke-width=\"1.4\"/><line x1=\"61\" y1=\"25\" x2=\"72\" y2=\"25\" stroke=\"#4a2311\" stroke-width=\"1.2\"/><line x1=\"61\" y1=\"31\" x2=\"72\" y2=\"31\" stroke=\"#4a2311\" stroke-width=\"1.2\"/>"
